#!/usr/bin/env python3\n\"\"\"\n行为树模块单元测试\n\"\"\"\n\nimport pytest\nimport math\nfrom control.planner import (\n    NodeStatus, BehaviorTreeBuilder, IsAtTarget, IsBatteryLow,\n    MoveTo, Pickup, Place, Charge\n)\n\n\nclass TestBehaviorTree:\n    \"\"\"行为树测试类\"\"\"\n\n    def test_condition_nodes(self):\n        \"\"\"测试条件节点\"\"\"\n        # 测试IsAtTarget\n        condition = IsAtTarget(target=(1.0, 1.0), tolerance=0.1)\n        condition.blackboard[\"current_x\"] = 1.05\n        condition.blackboard[\"current_y\"] = 0.98\n        assert condition.check() == True\n\n        condition.blackboard[\"current_x\"] = 2.0\n        assert condition.check() == False\n\n        # 测试IsBatteryLow\n        battery_condition = IsBatteryLow(threshold=0.2)\n        battery_condition.blackboard[\"battery_level\"] = 0.15\n        assert battery_condition.check() == True\n        battery_condition.blackboard[\"battery_level\"] = 0.3\n        assert battery_condition.check() == False\n\n    def test_move_to_action(self):\n        \"\"\"测试MoveTo动作节点\"\"\"\n        move = MoveTo(target=(2.0, 0.0))\n        move.blackboard[\"current_x\"] = 0.0\n        move.blackboard[\"current_y\"] = 0.0\n        move.blackboard[\"current_theta\"] = 0.0\n        move.blackboard[\"current_time\"] = 0.0\n\n        # 第一次tick，应该返回RUNNING\n        status = move.tick()\n        assert status == NodeStatus.RUNNING\n        assert move.trajectory is not None\n\n        # 模拟移动到接近目标\n        move.blackboard[\"current_x\"] = 1.95\n        move.blackboard[\"current_y\"] = 0.02\n        move.blackboard[\"current_time\"] = 10.0\n        status = move.tick()\n        assert status == NodeStatus.SUCCESS\n\n    def test_warehouse_transfer_task(self):\n        \"\"\"测试仓库搬运任务完整行为树\"\"\"\n        bt = BehaviorTreeBuilder.create_warehouse_transfer_task(\n            pick_location=(1.0, 0.0),\n            place_location=(3.0, 0.0),\n            charge_station=(0.0, 0.0)\n        )\n\n        # 初始化黑板\n        bt.blackboard.update({\n            \"current_x\": 0.0,\n            \"current_y\": 0.0,\n            \"current_theta\": 0.0,\n            \"current_time\": 0.0,\n            \"battery_level\": 0.8,\n            \"obstacles\": []\n        })\n\n        # 第一次tick，应该开始移动到取货点\n        status = bt.tick()\n        assert status == NodeStatus.RUNNING\n        assert bt.blackboard[\"desired_velocity\"] > 0.0\n\n        # 模拟到达取货点\n        bt.blackboard[\"current_x\"] = 1.0\n        bt.blackboard[\"current_y\"] = 0.0\n        bt.blackboard[\"current_time\"] = 5.0\n        status = bt.tick()\n        assert status == NodeStatus.RUNNING\n\n        # 模拟抓取完成\n        bt.blackboard[\"current_time\"] = 7.0\n        status = bt.tick()\n        assert bt.blackboard[\"held_object\"] == \"cargo_01\"\n\n        # 模拟低电量，应该去充电\n        bt.blackboard[\"battery_level\"] = 0.15\n        status = bt.tick()\n        assert status == NodeStatus.RUNNING\n\n    def test_patrol_task(self):\n        \"\"\"测试巡逻任务行为树\"\"\"\n        bt = BehaviorTreeBuilder.create_patrol_task([\n            (0.0, 0.0), (2.0, 0.0), (2.0, 2.0), (0.0, 2.0)\n        ])\n\n        bt.blackboard.update({\n            \"current_x\": 0.0,\n            \"current_y\": 0.0,\n            \"current_theta\": 0.0,\n            \"current_time\": 0.0,\n            \"battery_level\": 0.9,\n            \"obstacles\": []\n        })\n\n        status = bt.tick()\n        assert status == NodeStatus.RUNNING\n\n        # 模拟到达第一个巡逻点\n        bt.blackboard[\"current_x\"] = 2.0\n        bt.blackboard[\"current_y\"] = 0.0\n        bt.blackboard[\"current_time\"] = 5.0\n        status = bt.tick()\n        assert status == NodeStatus.RUNNING\n\n    def test_obstacle_avoidance(self):\n        \"\"\"测试避障功能\"\"\"\n        move = MoveTo(target=(3.0, 0.0))\n        move.blackboard.update({\n            \"current_x\": 1.0,\n            \"current_y\": 0.0,\n            \"current_theta\": 0.0,\n            \"current_time\": 0.0,\n            \"obstacles\": [(2.0, 0.0, 0.3)]  # 前方有障碍物\n        })\n\n        status = move.tick()\n        assert status == NodeStatus.RUNNING\n\n\nif __name__ == \"__main__\":\n    pytest.main([__file__, \"-v\"])\n